CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS audit_events(id BIGSERIAL PRIMARY KEY,ts TIMESTAMPTZ NOT NULL DEFAULT now(),event_type TEXT NOT NULL,instance_id TEXT NOT NULL,payload JSONB NOT NULL);
CREATE INDEX IF NOT EXISTS audit_events_ts_idx ON audit_events(ts DESC);
CREATE TABLE IF NOT EXISTS memories(id BIGSERIAL PRIMARY KEY,ts TIMESTAMPTZ NOT NULL DEFAULT now(),memory_type TEXT NOT NULL,subject TEXT NOT NULL,summary TEXT NOT NULL,evidence JSONB NOT NULL DEFAULT '{}'::jsonb,confidence DOUBLE PRECISION NOT NULL DEFAULT .5,expires_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS memories_subject_idx ON memories(subject,ts DESC);
CREATE TABLE IF NOT EXISTS strategies(strategy_id TEXT PRIMARY KEY,version INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL,spec JSONB NOT NULL,metrics JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hypotheses(hypothesis_id TEXT PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),subject TEXT NOT NULL,statement TEXT NOT NULL,counter_hypothesis TEXT NOT NULL,priority DOUBLE PRECISION NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',evidence JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS experiments(experiment_id TEXT PRIMARY KEY,hypothesis_id TEXT,strategy_id TEXT,dataset_hash TEXT NOT NULL,parameters JSONB NOT NULL,results JSONB,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decisions(decision_id TEXT PRIMARY KEY,ts TIMESTAMPTZ NOT NULL DEFAULT now(),world_version BIGINT NOT NULL,instrument TEXT,context JSONB NOT NULL,decision JSONB NOT NULL,outcome JSONB);
CREATE TABLE IF NOT EXISTS fills(fill_id TEXT PRIMARY KEY,ts TIMESTAMPTZ NOT NULL DEFAULT now(),venue TEXT,instrument TEXT,strategy_id TEXT,qty DOUBLE PRECISION,price DOUBLE PRECISION,fees DOUBLE PRECISION DEFAULT 0,payload JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS connector_health(connector TEXT PRIMARY KEY,state TEXT NOT NULL,last_event_ts TIMESTAMPTZ,last_ok_ts TIMESTAMPTZ,details JSONB NOT NULL DEFAULT '{}'::jsonb);
